def standard_anlegen(apps, schema_editor):
    """Übernimmt die bisherige tägliche Sicherung aus .env als Standard-Auftrag (ADR 0042)."""
    auftrag = apps.get_model("core", "SicherungsAuftrag")
    uhrzeit = os.environ.get("BINTAFELN_SICHERUNG_UHRZEIT", "02:30")
    if not re.fullmatch(r"([01][0-9]|2[0-3]):[0-5][0-9]", uhrzeit):
        uhrzeit = "02:30"
    anzahl = os.environ.get("BINTAFELN_SICHERUNG_ANZAHL", "14")
    auftrag.objects.create(
        name="Tägliche Sicherung auf dem Server",
        standard=True,
        uhrzeit=dt.time.fromisoformat(uhrzeit),
        anzahl=int(anzahl) if anzahl.isdigit() and int(anzahl) > 0 else 14,
        # Wie bisher: die erste planmäßige Sicherung zur nächsten Uhrzeit, nicht sofort
        geplant_am=dt.date.today(),
    )


def standard_loeschen(apps, schema_editor):
    apps.get_model("core", "SicherungsAuftrag").objects.all().delete()


